import { readFile } from 'node:fs/promises'
import { createProject, FluentXmlFluentTest, XmlFluentXmlTest } from '../test-utils'
import { Project } from '../../src'
import { path } from '@servicenow/sdk-build-core'

const SCOPE = 'x_cs'

interface TestCase {
    rootDir?: string
    tsFile: string
    xmlFile: string
    moduleFile?: string
}

const fluentToXmlCases: TestCase[] = [
    {
        tsFile: 'fixtures/fluent-to-xml/script-action-simple/script-action.now.ts',
        xmlFile: 'fixtures/fluent-to-xml/script-action-simple/script-action.xml',
    },
    {
        tsFile: 'fixtures/fluent-to-xml/script-action-now-include/script-action-now-include.now.ts',
        xmlFile: 'fixtures/fluent-to-xml/script-action-now-include/script-action-now-include.xml',
    },
    {
        tsFile: 'fixtures/fluent-to-xml/script-action-module/fluent/script-action-module.now.ts',
        moduleFile: 'fixtures/fluent-to-xml/script-action-module/server/module.ts',
        xmlFile: 'fixtures/fluent-to-xml/script-action-module/fluent/script-action-module.xml',
    },
]

const xmlToFluentCases: TestCase[] = [
    {
        tsFile: 'fixtures/xml-to-fluent/script-action-simple-defaults/script-action.now.ts',
        xmlFile: 'fixtures/xml-to-fluent/script-action-simple-defaults/script-action.xml',
    },
    {
        tsFile: 'fixtures/xml-to-fluent/script-action-simple-non-defaults/script-action.now.ts',
        xmlFile: 'fixtures/xml-to-fluent/script-action-simple-non-defaults/script-action.xml',
    },
]

const modulesTest = {
    path: 'fixtures/modules',
    expectedFileSysId: 'sysevent_script_action_297dd820b488470e9074074bd28a5d6a.xml',
}

describe('Script Action plugin', () => {
    describe('Fluent to XML', () => {
        test.each(fluentToXmlCases)('creates XML from %s', async ({ tsFile, xmlFile, moduleFile }) => {
            const project = createProject({ config: { scope: SCOPE } })

            const config = project.getConfig()

            const file = project.addFile({
                path: moduleFile ? `${config.fluentDir}/${path.basename(tsFile)}` : `${__dirname}/${tsFile}`,
                content: await readFile(`${__dirname}/${tsFile}`, 'utf8'),
            })

            if (moduleFile) {
                project.addFile({
                    path: `${config.serverModulesDir}/${path.basename(moduleFile)}`,
                    content: await readFile(`${__dirname}/${moduleFile}`, 'utf8'),
                })
            }

            project.registerExplicitId(
                'sysevent_script_action',
                'sample-script-action',
                '62029453210f4c69b767d6172a45410c'
            )
            const output = await file.getOutput()
            expect(output).toHaveLength(1)

            const expected = await readFile(`${__dirname}/${xmlFile}`, 'utf8')
            expect(output[0].content.trim()).toEqual(expected.trim())
        })
    })

    describe('XML to Fluent (no `Now.include()`)', () => {
        test.each(xmlToFluentCases)('creates Fluent from %s', async ({ tsFile, xmlFile }) => {
            const project = createProject({ config: { scope: SCOPE } })
            const result = await project.transform(`${__dirname}/${xmlFile}`)
            const content = result.changedFiles[0]?.getContent()
            const expected = await readFile(`${__dirname}/${tsFile}`, 'utf8')
            expect(content.trim()).toEqual(expected.trim())
        })
    })

    describe('Fluent to XML to Fluent', () => {
        test('creates Fluent to XML to Fluent from %s', async () => {
            const project = createProject()
            const fxf = new FluentXmlFluentTest(project)
            const id = fxf.addId('sysevent_script_action', 'sample-script-action')
            const fileContent = await readFile(`${__dirname}/${fluentToXmlCases[0].tsFile}`, 'utf8')
            fxf.addFluentFragment(fileContent)
            fxf.addExpectedXmlFileNames(`sysevent_script_action_${id}.xml`)

            await fxf.verify()
        })
    })

    describe('XML to Fluent to XML', () => {
        test('creates XML to Fluent to XML from %s', async () => {
            const project = createProject({
                rootDir: __dirname,
                config: { scope: SCOPE },
            })
            const originalFiles = [
                {
                    path: 'sysevent_script_action_62029453210f4c69b767d6172a45410c.xml',
                    content: await readFile(`${__dirname}/${xmlToFluentCases[0].xmlFile}`, 'utf8'),
                },
            ]
            const xfx = new XmlFluentXmlTest(project, __dirname, originalFiles)
            await xfx.verify()
        })
    })

    describe('Module scripts', () => {
        test('importing a module function should work', async () => {
            const project = new Project({ rootDir: path.join(__dirname, modulesTest.path) })
            const output = await project.getOutput()

            expect(output).toHaveLength(5)
            expect(output.find((f) => f.path.endsWith(modulesTest.expectedFileSysId))).toMatchObject({
                content: await readFile(
                    path.join(__dirname, modulesTest.path, 'expected', modulesTest.expectedFileSysId),
                    'utf-8'
                ),
            })
        })
    })
})
